 layout.Controls.Add(new Label{Text="修复勾选的格式；卸载恢复全部格式的旧设置。首次生成较慢。\r\n已打开的桌面可能需要重新登录 Windows 后更新。",Dock=DockStyle.Fill,ForeColor=Color.FromArgb(170,187,204)},0,5);
 var bottom=new FlowLayoutPanel{Dock=DockStyle.Fill};bottom.Controls.Add(new Label{Text="作者：BA2IA   QQ：21780   感谢 Codex\r\nMIT 开源 · 可自由使用、修改、分发（保留许可）",AutoSize=true});var license=new LinkLabel{Text="许可证",AutoSize=true,LinkColor=Color.LightSkyBlue};license.LinkClicked+=delegate{Open("LICENSE");};var third=new LinkLabel{Text="第三方许可与限制",AutoSize=true,LinkColor=Color.LightSkyBlue};third.LinkClicked+=delegate{Open("THIRD-PARTY-NOTICES.txt");};bottom.Controls.Add(license);bottom.Controls.Add(third);var about=new LinkLabel{Text="软件介绍 / 全部格式",AutoSize=true,LinkColor=Color.LightSkyBlue};about.LinkClicked+=delegate{ShowMessage("3DSTL 是免费的本地模型缩略图工具，让资源管理器和桌面直接显示模型预览。\\n\\n模型渲染：STL、3MF、OBJ、PLY、OFF、AMF、STEP、STP。\\n图片或路径预览：GCODE、GCO。\\n仅提取内置预览：SLDPRT、SLDASM、SLDDRW、PRTDOT、ASMDOT、DRWDOT、EPRT、EASM、EDRW。\\n\\n作者：BA2IA\\nQQ：21780\\n感谢 Codex\\n原创源码采用 MIT 许可，可自由使用、修改和分发，须保留版权及许可证。第三方组件遵循各自许可证。".Replace("\\n",Environment.NewLine),"关于 3DSTL",MessageBoxButtons.OK,MessageBoxIcon.Information);};bottom.Controls.Add(about);layout.Controls.Add(bottom,0,6);
 repair.Click+=delegate{var selected=formats.CheckedIndices.Cast<int>().Select(i=>AssociationManager.Formats[i]).ToArray();if(selected.Length==0){status.Text="请先勾选需要修复的格式。";return;}Run(()=>{manager.Repair(selected);return "已修复 "+selected.Length+" 种格式。返回目录按 F5 查看。";});};uninstall.Click+=delegate{if(ShowMessage("卸载全部模型缩略图功能并恢复原关联？\r\n模型文件不会删除。","卸载",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes)Run(manager.Uninstall);};refresh.Click+=delegate{UpdateStatus();};UpdateStatus();ApplyLanguage(this);Text=english?"3DSTL · Model Thumbnails":"3DSTL · 模型缩略图管理";}
 DialogResult ShowMessage(string text,string caption,MessageBoxButtons buttons,MessageBoxIcon icon){return MessageBox.Show(this,Translate(text),Translate(caption),buttons,icon);}
