 void Open(string file){Process.Start(new ProcessStartInfo(Path.Combine(manager.Root,file)){UseShellExecute=true});}
 void UpdateStatus(){var checks=formats.CheckedIndices.Cast<int>().ToHashSet();formats.Items.Clear();int active=0;foreach(string ext in AssociationManager.Formats){bool installed=manager.Active(ext);if(installed)active++;formats.Items.Add("."+ext.ToUpperInvariant()+"  "+(installed?"已启用":"未启用")+(Array.IndexOf(AssociationManager.Formats,ext)>=10?" · 内置预览":""),installed||checks.Contains(formats.Items.Count));}status.Text=english?"Enabled: "+active+" / "+AssociationManager.Formats.Length:"当前已启用 "+active+" / "+AssociationManager.Formats.Length+" 种格式。";for(int i=0;i<formats.Items.Count;i++)formats.Items[i]=Translate(formats.Items[i].ToString());}
 void Run(Func<string> operation){try{string message=operation();UpdateStatus();status.Text=Translate(message);}catch(Exception e){status.Text=Translate(e.Message);ShowMessage(e.Message,"操作未完成",MessageBoxButtons.OK,MessageBoxIcon.Warning);}}
 [STAThread]static void Main(string[] args){Application.EnableVisualStyles();if(args.Length>1&&args[0]=="--repair"){try{new AssociationManager().Repair(args.Skip(1).Where(x=>AssociationManager.Formats.Contains(x)).ToArray());}catch(Exception e){File.WriteAllText(Path.Combine(AppContext.BaseDirectory,"repair-error.txt"),e.Message);Environment.ExitCode=1;}return;}if(args.Contains("--selftest")){SelfTest();return;}using(var form=new ManagerForm()){if(args.Length==2&&(args[0]=="--snapshot"||args[0]=="--snapshot-en")){if(args[0]=="--snapshot-en"){form.english=true;form.UpdateStatus();form.ApplyLanguage(form);form.Text="3DSTL · Model Thumbnails";}form.Show();Application.DoEvents();using(var bmp=new Bitmap(form.Width,form.Height)){form.DrawToBitmap(bmp,new Rectangle(Point.Empty,bmp.Size));bmp.Save(args[1]);}return;}Application.Run(form);}}
 static void SelfTest(){var m=new AssociationManager();string token=Guid.NewGuid().ToString("N");m.RegistryRoot="Software\\AuxModelPreviewTest\\"+token;m.BackupFile=Path.Combine(Path.GetTempPath(),"AuxModelPreviewTest-"+token+".json");string key=m.RegistryRoot+"\\.stl\\shellex\\{e357fccd-a995-4576-b01f-234630154e96}";using(var k=Registry.CurrentUser.CreateSubKey(key))k.SetValue("","{OLD-PROVIDER}");m.Repair(new[]{"stl","obj"});if(!m.Active("stl")||!m.Active("obj"))throw new Exception("Registration failed");m.Repair(new[]{"stl"});m.Uninstall();using(var k=Registry.CurrentUser.OpenSubKey(key))if(Convert.ToString(k.GetValue(""))!="{OLD-PROVIDER}")throw new Exception("Restore failed");if(m.Active("obj"))throw new Exception("Uninstall failed");Registry.CurrentUser.DeleteSubKeyTree(m.RegistryRoot,false);File.Delete(m.BackupFile);Console.WriteLine("PASS repair, repeated repair, restore old association, uninstall");}
